  ["bitlife","other","LifeBit.html","bitlife"],
  ["draw joust","action","Draw Joust.html","drawjoust"],
  ["google baseball","sports","Google Baseball.html","googlebaseball"],
  ["growden","io","Growden.io.html","growden"],
  ["raft","action","Raft.html","raft"],
  ["escape road 2","racing","Escape Road 2.html","escaperoad2"],
  ["rl 2d","sports","rl2d.html","rl2d"],
  ["terraria","action","Terraria.html","terraria"],
  ["fih","sports","Fih.html","fih"],
  ["basketball stars","sports","Basketball Stars.html","basketballstars"],
  ["backrooms","horror","Backrooms.html","backrooms"],
  ["bart blast","action","Bart Blast.html","bartblast"],
  ["bitplanes","action","BitPlanes.html","bitplanes"],
  ["bloons td 6","other","Bloons TD.html","bloonstd"],
  ["boxing random","sports","Boxing Random.html","boxingrandom"],
  ["brawl guys","action","Brawl Guys.html","brawlguys"],
  ["brotato","action","Brotato.html","brotato"],
  ["buckshot roulette","horror","Buckshot Roulette.html","buckshotroulette"],
  ["buildnow.gg","shooting","BuildNow.gg.html","buildnow"],
  ["bust a loop","racing","Bust a Loop.html","bustalloop"],
  ["cat vs roomba","action","Cat vs Roomba.html","catvsroomba"],
  ["christmas massacre","horror","Christmas Massacre.html","christmasmassacre"],
  ["cookie clicker","other","Cookie Clicker.html","cookieclicker"],
  ["sonic.exe","horror","Sonic.EXE (ORIGINAL).html","sonicexe"],
  ["sort the court","other","Sort the Court.html","sortthecourt"],
  ["fnf soft","other","Friday Night Funkin Soft.html","fnfsoft"],
  ["fnf spongebob","other","fnf spongebob.html","fnf spongebob"],
  ["soccer random","sports","Soccer Random.html","soccerrandom"],
  ["404 soccer","sports","404 soccer.html","404soccer"],
  ["steal brainrot online","io","Steal Brainrot Online.html","stealbrainrot"],
  ["retro bowl","sports","Retro Bowl.html","retrobowl"],
  ["retro bowl college","sports","Retro Bowl College.html","retrobowlcollege"],
  ["poly track","racing","Poly Track.html","polytrack"],
  ["tabs","action","Totally Accurate Battle Simulator (TABS).html","tabs"],
  ["schoolboy runaway","horror","Schoolboy Runaway.html","schoolboyrunaway"],
  ["a small world cup","sports","A Small World Cup.html","asmallworldcup"],
  ["getting over it","action","Getting Over It with Bennett Foddy.html","gettingoverit"],
  ["kindergarten","horror","Kindergarten.html","kindergarten"],
  ["kindergarten 2","horror","kindergarten 2.html","kindergarten 2"],
  ["kindergarten 3","horror","kindergarten 3.html","kindergarten 3"],
  ["plants vs zombies","other","Plants vs. Zombies GOTY Edition.html","pvzgoty"],
  ["fortnite battle royale","shooting","Fortzone Battle Royale.html","fortzone"],
  ["five nights at shreks hotel","horror","Five Nights at Shreks Hotel.html","shrek1"],
  ["golf classic","sports","Golf Classic.html","Golf"],
  ["13th floor","horror","13th Floor.html","floor"],
  ["geometry dash","action","Geometry Dash.html","geometry"],
  ["12 mini battles","action","12 Mini Battles.html","12"],
  ["justfall.lol","io","JustFall.lol.html","justfall"],
  ["lethal company","horror","Lethal Company.html","lethalcompany"],
  ["evowars.io","io","EvoWars.io.html","evowars"],
  ["bombfighters","action","Bombfighters.html","bombfighters"],
  ["bowmasters","action","Bowmasters.html","bowmasters"],
  ["bitgun.io","io","BitGun.io.html","bitgun"],
  ["whos your daddy","action","whos your daddy.html","whos ur daddy"],
  ["lethal ape","action","lethal ape.html","lethal ape"],
  ["yohohoio","io","yohohoio.html","yohohoho"],
  ["peak","action","peak.html","peak"],
  ["how to fish","other","how to fish.html","how to fish"],
  ["hammer 2 reloaded","action","hammer-2 reloaded.html","hammer 2 reloaded"],
  ["hill climb racing","racing","hill climb racing.html","hill climb"],
  ["skate 3","sports","skate 3.html","skate 3"],
  ["gamble with your friends","other","gamble with-your friends.html","gamble with your friends"],
  ["castle crashers","action","castle crashers.html","castle crashers"],
  ["midnight shift","horror","midnight shift.html","midnight"],
  ["tung sahur horror","horror","tung sahur horror.html","tung sahur"],
  ["the man from the window","horror","the man from the window.html","the man"],
  ["fnaf","horror","fnaf.html","fnaf"],
  ["fnaf 2","horror","fnaf 2.html","fnaf 2"],
  ["fnaf 3","horror","fnaf 3.html","fnaf 3"],
  ["fnaf 4","horror","fnaf 4.html","fnaf 4"],
  ["scary shawarma","horror","scary shawarma.html","scary kiosk"],
  ["blockpost","shooting","BlockPost.html","block post"],
  ["snow rider 3d","racing","snow rider 3d.html","snow rider 3d"],
  ["getaway shootout","shooting","getaway shootout.html","getaway shootout"],
  ["grand theft auto 3","action","grand theft auto 3.html","gta 3"],
  ["beeswarm simulator","other","beeswarm simulator.html","bee swarm"],
  ["survivorio","io","survivorio.html","survivorio"],
  ["super mario 64","action","super mario 64.html","super mario"],
  ["super mario kart","action","Super Mario Kart.html","mario kart"],
  ["super smash bros","action","Super Smash Bros.html","super smash bros"],
  ["ragdoll archers","action","ragdoll archers.html","ragdoll"],
  ["wrassling","sports","wrassling.html","wraslling"],
  ["wheelie bike 2","racing","wheelie bike 2.html","wheelie bike"],
  ["gun mayhem 2","shooting","gun mayhem 2.html","gun mayhem 2"],
  ["that's not my neighbor","horror","That's Not My Neighbor.html","thatsnotmyneighbor"],
  ["gang beasts (WORKING)","action","Gang Beasts.html","gangbeasts"],
  ["n-gon","action","n gon.html","n gon"],
  ["dogeminer","action","Doge Miner.html","dogeminer"],
  ["retro ping pong","action","retro ping pong.html","retro ping pong"],
  ["Brawl Stars","action","Brawl Stars.html","Brawl Stars"],
  ["1 on 1 soccer","sports","1 on 1 Soccer.html","1 on 1 soccer"],
  ["paper.io","io","Paperio.html","paperio"],
  ["soflo wheelie life","racing","Soflo Wheelie Life.html","soflo"],
  ["rocket goal.io","sports","Rocket Goal.io.html","rocketgoalio"],
  ["garten of banban","action","Garten of Banban.html","garten of banban"],
  ["duck life","action","Duck Life.html","duck life"],
  ["superhot","action","superhot webport.html","superhot"],
  ["Minecraft Mods (NEW)","action","MineCraft.html","minecraft"],
  ["RNG","action","RNG.html","rng"],
  ["infinite craft","action","Infinite Craft.html","infinite craft"],
  ["MVP Baseball","action","MVP Baseball.html","mvp baseball"],
];

const REPORT_EMAIL = '';   // put your email here to have reports open in the email app

/* ---------- element references ---------- */
const grid = document.getElementById('grid');
const searchEl = document.getElementById('search'), countEl = document.getElementById('count');
const player = document.getElementById('game-player'), frame = document.getElementById('game-frame');
const helpEl = document.getElementById('help');
const reportEl = document.getElementById('report'), rStatus = document.getElementById('report-status');
const loader = document.getElementById('loader'), fill = document.getElementById('load-fill');
const loadSub = document.getElementById('load-subtext');

/* ---------- saved favorites / recents ---------- */
const store = {
  get(k) { try { return JSON.parse(localStorage.getItem(k)) || []; } catch (e) { return []; } },
  set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
};
let favs = store.get('mk_favs'), recents = store.get('mk_recents'), tab = 'games', curFile = '', curTitle = '';
const APP_FILES = ['Chat Bot AI (A.I GPT).html','movies.html','Music.html','google.html','Soundboard.html','Auto Clicker.html'];   // these show under the apps tab

/* ---------- images: queued, remembers which extension works, fades in ---------- */
let EXTS = ['png','jpg','webp'];
function cardCandidates(base) {
  const names = [base, base.charAt(0).toUpperCase() + base.slice(1)];
  return names.flatMap(n => EXTS.map(e => ({ src: IMG_DIR + encodeURIComponent(n) + '.' + e, ext: e })));
}
function tryImages(candidates, onFound, onDone) {
  let i = 0;
  (function next() {
    if (i >= candidates.length) { onDone(); return; }
    const c = candidates[i++], im = new Image();
    im.decoding = 'async';
    im.onload = () => {
      EXTS = [c.ext].concat(EXTS.filter(x => x !== c.ext));   // try the working extension first next time
      onFound(im); onDone();
    };
    im.onerror = next;
    im.src = c.src;
  })();
}
// only a few images load at once so scrolling stays smooth
const imgQueue = []; let imgActive = 0;
function pumpImages() {
  while (imgActive < 12 && imgQueue.length) {
    imgActive++;
    imgQueue.shift()(() => { imgActive--; pumpImages(); });
  }
}
const loadCard = c => {
  if (c._loaded) return;
  c._loaded = true;
  imgQueue.push(done => tryImages(cardCandidates(c._img), im => {
    c._bg.textContent = '';
    c._bg.appendChild(im);
    requestAnimationFrame(() => im.classList.add('in'));
  }, done));
  pumpImages();
};

/* ---------- loading screen ---------- */
let gameLoading = false, gameFrameLoaded = false, gameMinDone = false, loadId = 0, gameTimer = null;

let barP = 0, barRaf = 0, barDone = false;
function setBar(p) { barP = p; fill.style.transform = 'scaleX(' + p + ')'; }
function runBar() {
  cancelAnimationFrame(barRaf);
  let last = performance.now();
  (function step(now) {
    const dt = Math.min(now - last, 50); last = now;
    if (barDone) {
      setBar(Math.min(1, barP + dt * 0.006));          // finish quickly but smoothly
    } else {
      setBar(barP + (0.92 - barP) * (dt / 900));       // eases toward 92% and never stalls or jumps
    }
    if (barP < 1) barRaf = requestAnimationFrame(step);
  })(last);
}
function showLoader() {
  barDone = false; setBar(0);
  loader.classList.add('show');
  runBar();
}
function hideLoader() {
  barDone = true; runBar();                              // glide to 100%, then fade the screen out
  setTimeout(() => { if (!gameLoading) loader.classList.remove('show'); }, 260);
}

// a game is only revealed once its iframe has loaded AND the minimum time has passed
function startGameLoad() {
  const id = ++loadId;
  gameLoading = true; gameFrameLoaded = false; gameMinDone = false;
  showLoader();
  setTimeout(() => { if (id === loadId) { gameMinDone = true; tryFinishGame(); } }, 1500);
  clearTimeout(gameTimer);
  gameTimer = setTimeout(() => { if (id === loadId) { gameFrameLoaded = true; tryFinishGame(); } }, 20000); // safety net
}
function tryFinishGame() {
  if (!gameLoading || !gameFrameLoaded || !gameMinDone) return;
  gameLoading = false;
  clearTimeout(gameTimer);
  hideLoader();
}
frame.addEventListener('load', () => {
  if (gameLoading && frame.getAttribute('src') === gameUrl(curFile)) {
    gameFrameLoaded = true;
    tryFinishGame();
  }
});

/* ---------- building the grid ---------- */
const STAR = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M12 2.5l2.9 6 6.6.9-4.8 4.6 1.2 6.5L12 17.4l-5.9 3.1 1.2-6.5-4.8-4.6 6.6-.9z"/></svg>';
const PLAY = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>';

function makeCard([title, cat, file, img], idx) {
  const card = document.createElementNS('http://www.w3.org/1999/xhtml','div');
  card.className = 'card'; card.tabIndex = 0; card.setAttribute('role', 'button');
  card.dataset.cat = cat; card.dataset.file = file; card.dataset.title = title.toLowerCase();
  card.innerHTML = '<div class="card-bg"></div><div class="card-shade"></div><button class="fav" aria-label="Favorite">' + STAR + '</button><div class="play">' + PLAY + '</div><div class="card-title"></div>';
  card.querySelector('.card-title').textContent = title;
  card._bg = card.querySelector('.card-bg');
  card._bg.textContent = title.replace(/[^a-z0-9 ]/gi, '').split(' ').filter(Boolean).slice(0, 2).map(w => w[0]).join('').toUpperCase(); card._img = img; card._idx = idx;
  card.querySelector('.fav').onclick = e => { e.stopPropagation(); toggleFav(file); };
  card.onclick = () => openGame(file, title);
  card.onkeydown = e => { if (e.target === card && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); openGame(file, title); } };
  return card;
}

let cards = [];
const emptyMsg = document.createElementNS('http://www.w3.org/1999/xhtml','div');
emptyMsg.className = 'empty';

function buildGrid() {
  grid.innerHTML = '';
  const frag = document.createDocumentFragment();
  cards = GAMES.map((g, i) => { const c = makeCard(g, i); frag.appendChild(c); return c; });
  frag.appendChild(emptyMsg);
  grid.appendChild(frag);

  if ('IntersectionObserver' in window) {
    const io = new IntersectionObserver(es => es.forEach(e => {
      if (e.isIntersecting) { io.unobserve(e.target); loadCard(e.target); }
    }), { root: document.querySelector('.page'), rootMargin: '700px' });
    cards.forEach(c => io.observe(c));
  } else cards.forEach(loadCard);

  render();
}

/* ---------- search, category, tabs, favorites ---------- */
const PAGE_SIZE = 50;
let curPage = 1;
const pager = document.getElementById('pager'), pgPrev = document.getElementById('pg-prev'), pgNext = document.getElementById('pg-next'), pgInfo = document.getElementById('pg-info');
function goPage(n) {
  curPage = n; render();
  document.querySelector('.page').scrollTop = 0;
}
pgPrev.onclick = () => goPage(curPage - 1);
pgNext.onclick = () => goPage(curPage + 1);

function render() {
  const q = searchEl.value.toLowerCase().trim();
  const word = tab === 'apps' ? 'apps' : 'games';
  const matches = [];
  cards.forEach(c => {
    const f = c.dataset.file;
    c.classList.toggle('is-fav', favs.includes(f));
    const ok = (APP_FILES.includes(f) === (tab === 'apps')) && c.dataset.title.includes(q);
    c.style.order = c._idx;
    c._match = ok;
    if (ok) matches.push(c);
  });
  const shown = matches.length;
  const pages = Math.max(1, Math.ceil(shown / PAGE_SIZE));
  if (curPage > pages) curPage = pages;
  if (curPage < 1) curPage = 1;
  const start = (curPage - 1) * PAGE_SIZE;
  const visible = new Set(matches.slice(start, start + PAGE_SIZE));
  cards.forEach(c => { c.style.display = visible.has(c) ? '' : 'none'; });
  pgInfo.textContent = curPage + ' / ' + pages;
  pgPrev.disabled = curPage <= 1;
  pgNext.disabled = curPage >= pages;
  pager.style.display = pages > 1 ? '' : 'none';
  countEl.textContent = 'loaded ' + shown + ' ' + word;
  searchEl.placeholder = 'search ' + word + '...';
  emptyMsg.textContent = 'NO ' + word.toUpperCase() + ' FOUND';
  emptyMsg.style.order = 9999;
  emptyMsg.style.display = shown ? 'none' : 'block';
}
function toggleFav(file) {
  favs = favs.includes(file) ? favs.filter(f => f !== file) : favs.concat(file);
  store.set('mk_favs', favs); render();
}
let searchTimer;
searchEl.addEventListener('input', () => { clearTimeout(searchTimer); searchTimer = setTimeout(() => { curPage = 1; render(); }, 120); });
document.querySelectorAll('.tabs button').forEach(b => b.onclick = () => {
  tab = b.dataset.tab;
  document.querySelectorAll('.tabs button').forEach(x => x.classList.toggle('on', x === b));
  curPage = 1; render();
});

/* ---------- game player ---------- */
function gameUrl(file) {
  return GAME_DIR + encodeURIComponent(file);
}
function openGame(file, title) {
  curFile = file; curTitle = title;
  recents = [file].concat(recents.filter(f => f !== file)).slice(0, 20);
  store.set('mk_recents', recents);
  document.getElementById('gp-title').textContent = title;
  document.getElementById('root').classList.add('playing');   // stops the falling leaves so the game gets all the CPU
  startGameLoad();
  player.style.display = 'flex';
  frame.src = gameUrl(file);
  render();
}
function closeGame() {
  loadId++; gameLoading = false; clearTimeout(gameTimer);
  cancelAnimationFrame(barRaf);
  loader.classList.remove('show');
  player.style.display = 'none';
  frame.src = 'about:blank';
  document.getElementById('root').classList.remove('playing');
}
document.getElementById('gp-close').onclick = closeGame;
document.getElementById('gp-reload').onclick = () => { startGameLoad(); frame.src = 'about:blank'; setTimeout(() => { frame.src = gameUrl(curFile); }, 30); };
document.getElementById('gp-full').onclick = () => {
  const f = frame.requestFullscreen || frame.webkitRequestFullscreen;
  if (f) f.call(frame);
};

/* ---------- report a problem ---------- */
function openReport() {
  document.getElementById('report-game').textContent = 'Game: ' + curTitle;
  document.getElementById('report-note').value = ''; rStatus.textContent = '';
  reportEl.classList.add('open');
}
function closeReport() { reportEl.classList.remove('open'); }
document.getElementById('gp-report').onclick = openReport;
document.getElementById('report-x').onclick = closeReport;
reportEl.addEventListener('click', e => { if (e.target === reportEl) closeReport(); });
document.getElementById('report-send').onclick = () => {
  const note = document.getElementById('report-note').value.trim();
  const text = 'Game: ' + curTitle + ' (' + curFile + ')\nProblem: ' + document.getElementById('report-type').value + (note ? '\nDetails: ' + note : '');
  if (REPORT_EMAIL) {
    location.href = 'mailto:' + REPORT_EMAIL + '?subject=' + encodeURIComponent('Problem with ' + curTitle) + '&body=' + encodeURIComponent(text);
    rStatus.textContent = 'Opening your email app...';
  } else {
    if (navigator.clipboard) navigator.clipboard.writeText(text).catch(() => {});
    rStatus.textContent = 'Report copied. Send it to whoever runs the site.';
  }
  setTimeout(closeReport, 2200);
};

/* ---------- settings ---------- */
let settings = { cols: 5, leaves: true, titles: true };
try { Object.assign(settings, JSON.parse(localStorage.getItem('mk_settings')) || {}); } catch (e) {}
const saveSettings = () => { try { localStorage.setItem('mk_settings', JSON.stringify(settings)); } catch (e) {} };
function applySettings() {
  // fewer columns on small screens, same as the page always did
  const cap = innerWidth <= 600 ? 2 : innerWidth <= 850 ? 3 : innerWidth <= 1100 ? 4 : 99;
  grid.style.gridTemplateColumns = 'repeat(' + Math.min(settings.cols, cap) + ',1fr)';
  document.getElementById('root').classList.toggle('no-leaves', !settings.leaves);
  document.getElementById('root').classList.toggle('hide-titles', !settings.titles);
}
const setCols = document.getElementById('set-cols'), setLeaves = document.getElementById('set-leaves'), setTitles = document.getElementById('set-titles');
setCols.value = String(settings.cols); setLeaves.checked = !!settings.leaves; setTitles.checked = !!settings.titles;
setCols.onchange = () => { settings.cols = +setCols.value; saveSettings(); applySettings(); };
setLeaves.onchange = () => { settings.leaves = setLeaves.checked; saveSettings(); applySettings(); };
setTitles.onchange = () => { settings.titles = setTitles.checked; saveSettings(); applySettings(); };
addEventListener('resize', applySettings);
applySettings();

/* ---------- help ---------- */
function openHelp() { helpEl.classList.add('open'); }
function closeHelp() { helpEl.classList.remove('open'); }
document.getElementById('help-btn').onclick = () => helpEl.classList.contains('open') ? closeHelp() : openHelp();
document.getElementById('help-x').onclick = closeHelp;
helpEl.addEventListener('click', e => { if (e.target === helpEl) closeHelp(); });

addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  if (reportEl.classList.contains('open')) { closeReport(); return; }
  if (helpEl.classList.contains('open')) { closeHelp(); return; }
  if (player.style.display === 'flex') closeGame();
});

/* ---------- fall decoration ---------- */
const LEAF_COLORS = ['#e8741e','#c2410c','#d97706','#b91c1c','#f59e0b','#92400e','#dc2626'];
function buildFall() {
  const n = innerWidth < 600 ? 7 : 13;
  let out = '';
  for (let i = 0; i < n; i++) {
    out += '<svg xmlns="http://www.w3.org/2000/svg" class="lf" style="--x:' + (Math.random() * 100).toFixed(1) + 'vw;--s:' + (18 + Math.random() * 20).toFixed(0) + 'px;--d:' + (11 + Math.random() * 10).toFixed(1) +
           's;--delay:-' + (Math.random() * 20).toFixed(1) + 's;--dx:' + (Math.random() * 160 - 80).toFixed(0) + 'px;color:' +
           LEAF_COLORS[Math.floor(Math.random() * LEAF_COLORS.length)] + '"><use href="#leaf"/></svg>';
  }
  document.getElementById('fall').innerHTML = out;
}

/* ---------- start ---------- */
buildGrid();
buildFall();
document.addEventListener('visibilitychange', () => { document.getElementById('fall').style.display = document.hidden ? 'none' : ''; });
// no startup loader
